# merge-creds.ps1 — inject real server creds + IPs into worker/servers.json.
# Source: infra/credentials.json (generated by 05-Bootstrap.ps1) + infra/ips.txt.
# Usage:  pwsh -File worker/merge-creds.ps1
$ErrorActionPreference = "Stop"

$creds = Get-Content "$PSScriptRoot\..\infra\credentials.json" -Raw | ConvertFrom-Json
$payload = Get-Content "$PSScriptRoot\servers.json" -Raw | ConvertFrom-Json

foreach ($s in $payload.servers) {
  $c = $creds.($s.tag)
  if (-not $c) { throw "no creds for '$($s.tag)' in infra/credentials.json — run 05-Bootstrap.ps1 first" }
  $s.username = $c.username
  $s.password = $c.password
}

# real IPs from ips.txt (tag<TAB>instanceId<TAB>ip)
foreach ($line in Get-Content "$PSScriptRoot\..\infra\ips.txt") {
  $p = $line -split "`t"
  if ($p.Count -ge 3) {
    foreach ($s in $payload.servers) {
      if ($s.tag -eq $p[0]) { $s.ip = $p[2] }   # unconditional: ips.txt is authoritative
    }
  }
}

$payload.updated_at = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
$payload | ConvertTo-Json -Depth 4 | Set-Content "$PSScriptRoot\servers.json" -Encoding UTF8
Write-Host "servers.json updated with real creds ✓" -ForegroundColor Green
